from __future__ import annotations

import csv
import hashlib
import json
from collections import defaultdict
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Iterable

@dataclass
class FileRecord:
    path: str
    size: int
    sha256: str
    modified_utc: str
    accessed_utc: str
    changed_utc: str

def utc_iso(ts: float) -> str:
    return datetime.fromtimestamp(ts, tz=timezone.utc).isoformat()

def sha256_file(path: Path, chunk_size: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as handle:
        while True:
            chunk = handle.read(chunk_size)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()

def collect_files(evidence_root: Path) -> list[FileRecord]:
    records: list[FileRecord] = []
    for path in sorted(p for p in evidence_root.rglob('*') if p.is_file()):
        stat = path.stat()
        records.append(FileRecord(
            path=str(path.relative_to(evidence_root)),
            size=stat.st_size,
            sha256=sha256_file(path),
            modified_utc=utc_iso(stat.st_mtime),
            accessed_utc=utc_iso(stat.st_atime),
            changed_utc=utc_iso(stat.st_ctime),
        ))
    return records

def duplicate_groups(records: Iterable[FileRecord]) -> dict[str, list[str]]:
    grouped: dict[str, list[str]] = defaultdict(list)
    for record in records:
        grouped[record.sha256].append(record.path)
    return {digest: paths for digest, paths in grouped.items() if len(paths) > 1}

def write_csv(records: list[FileRecord], output: Path) -> None:
    with output.open('w', newline='', encoding='utf-8') as handle:
        writer = csv.DictWriter(handle, fieldnames=['path','size','sha256','modified_utc','accessed_utc','changed_utc'])
        writer.writeheader()
        for record in records:
            writer.writerow(asdict(record))

def write_json(records: list[FileRecord], output: Path) -> None:
    payload = {
        'generated_at_utc': datetime.now(timezone.utc).isoformat(),
        'file_count': len(records),
        'records': [asdict(record) for record in records],
    }
    output.write_text(json.dumps(payload, indent=2), encoding='utf-8')

def write_duplicates(records: list[FileRecord], output: Path) -> None:
    output.write_text(json.dumps({'duplicate_groups': duplicate_groups(records)}, indent=2), encoding='utf-8')
